    shr.b32 %r_r0, %r_tid, 4;
    and.b32 %r_c, %r_tid, 15;
    add.u32 %r_col, %r_kt, %r_c;
    setp.lt.u32 %p3, %r_col, %r_n;
    add.u32 %r_row, %r_by, %r_r0;
    mul.lo.u32 %r_tmp, %r_row, %r_n;
    add.u32 %r_tmp, %r_tmp, %r_col;
    mul.wide.u32 %rd_off, %r_tmp, 4;
    mul.wide.u32 %rd_rowstride, %r_n, 64;
    mul.lo.u32 %r_saddr, %r_c, 68;
    add.u32 %r_saddr, %r_saddr, %r_r0;
