    add.u64 %rd_addr, %rd_A, %rd_off;
    @%p2 ld.global.f32 %f_v, [%rd_addr];
    st.shared.f32 [%r_saddr+64], %f_v;
    add.u32 %r_row, %r_row, 16;
    add.u64 %rd_off, %rd_off, %rd_rowstride;
    mov.f32 %f_v, 0f00000000;
    setp.lt.u32 %p1, %r_row, %r_n;
