    // ---- stage B tile: sB[k][c] = B[(kt+k)*n + bx+c], 4 elems per thread ----
    shr.b32 %r_k, %r_tid, 6;
    and.b32 %r_c, %r_tid, 63;
    add.u32 %r_col, %r_bx, %r_c;
    setp.lt.u32 %p3, %r_col, %r_n;
    add.u32 %r_row, %r_kt, %r_k;
    mul.lo.u32 %r_tmp, %r_row, %r_n;
    add.u32 %r_tmp, %r_tmp, %r_col;
