    shl.b32 %r_saddr, %r_saddr, 2;
    add.u32 %r_saddr, %r_saddr, %r_sB;
    mov.f32 %f_v, 0f00000000;
    setp.lt.u32 %p1, %r_row, %r_n;
    and.pred %p2, %p1, %p3;
    add.u64 %rd_addr, %rd_B, %rd_off;
    @%p2 ld.global.f32 %f_v, [%rd_addr];
    st.shared.f32 [%r_saddr], %f_v;
    add.u32 %r_row, %r_row, 4;
    add.u64 %rd_off, %rd_off, %rd_rowstride;
    mov.f32 %f_v, 0f00000000;
    setp.lt.u32 %p1, %r_row, %r_n;
    and.pred %p2, %p1, %p3;
    add.u64 %rd_addr, %rd_B, %rd_off;
    @%p2 ld.global.f32 %f_v, [%rd_addr];
    st.shared.f32 [%r_saddr+1088], %f_v;
